const feed=$('Lire le catalogue du site').first().json;
if(feed?.product!=='cuisine-du-cambodge'||feed?.schemaVersion!==1||!Array.isArray(feed.items)) throw Error('catalogue_non_valide');
const history=$input.all().map(i=>i.json).filter(i=>i.source_id);
const previous=new Map(history.map(h=>[h.source_id,{fingerprint:h.source_fingerprint,seen:Number(h.uses||0),last:h.latest_date||''}]));
const kinds=['recette','technique','ingredient','recette','culture','recette','atelier'];
const todayParts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const part=(key)=>todayParts.find(p=>p.type===key)?.value;
const today=`${part('year')}-${part('month')}-${part('day')}`;
const desired=kinds[(new Date(today+'T12:00:00Z').getUTCDay()+6)%7];
const candidates=feed.items.filter(s=>s.imageUrl&&/^https:\/\/www\.cuisine-du-cambodge\.com\/social-assets\/[a-z0-9-]+\.jpg$/.test(s.imageUrl));
if(!candidates.length) throw Error('aucun_media_JPEG');
const ranked=candidates.map((s,index)=>{
 const p=previous.get(s.id); const fresh=!p; // An edited image or caption must not make a previously published source new.
 return {s,score:(fresh?1000:0)+(s.kind===desired?70:0)-(p?.seen||0)*40-index/10000};
}).sort((a,b)=>b.score-a.score);
const source=ranked[0].s;
return [{json:{source,scheduledDate:today,sourceId:source.id,fingerprint:source.fingerprint,imageUrl:source.imageUrl}}];

const s=$('Choisir un contenu original').first().json;
const clean=value=>String(value??'').replace(/\s+/g,' ').trim();
const source=s?.source||{},title=clean(source.title),rawFacts=Array.isArray(source.facts)?source.facts:[];
const facts=rawFacts.map(raw=>({raw,text:clean(raw)})).filter(f=>f.text.length>0);
if(!title||!facts.length||!facts.some(f=>f.text.length>=50))throw Error('catalogue_insuffisant_pour_legendes');
const pageUrl=clean(source.url);
if(typeof source.url!=='string'||!/^https:\/\/www\.cuisine-du-cambodge\.com\/[a-z0-9][a-z0-9\/_-]*\/?$/i.test(pageUrl))throw Error('catalogue_url_invalide');
const verified=[];for(const fact of facts)if(!verified.some(item=>item.text===fact.text))verified.push(fact);
const factByText=new Map(verified.map(fact=>[fact.text,fact]));
// Approaches are deliberately modest; all concrete culinary claims below must be catalog excerpts.
const intros={
  recette:{facebook:['Envie de cuisiner '+title+' ?',title+' : on passe en cuisine.'],instagram:[title+', à cuisiner et à partager.','Au menu : '+title+'.']},
  ingredient:{facebook:['Et si on parlait de '+title+' ?',title+' : des saveurs à découvrir.'],instagram:['Les parfums de '+title+'.','À la découverte de '+title+'.']},
  culture:{facebook:['Dans nos carnets : '+title+'.','À lire : '+title+'.'],instagram:[title+'.','Carnet du Cambodge : '+title+'.']},
  atelier:{facebook:[title+' : place à la pratique.','On explore ensemble '+title+'.'],instagram:['Le geste du jour : '+title+'.','En cuisine avec '+title+'.']},
  technique:{facebook:[title+' : tout est dans le geste.','On parle technique : '+title+'.'],instagram:['Un geste à connaître : '+title+'.','Zoom sur '+title+'.']}
};
const openings=intros[source.kind]||{facebook:['Et si on parlait de '+title+' ?'],instagram:['À découvrir : '+title+'.']};
const phrases={facebook:{openers:openings.facebook,closers:['À lire sur notre site :','Pour aller plus loin :']},instagram:{openers:openings.instagram,closers:['Pour en savoir plus, rendez-vous sur notre site.','La suite est à découvrir sur notre site.']}};
const fbTail='\n\n'+pageUrl,igTail='\n\ncuisine-du-cambodge.com';
// Avoid dumping raw ingredient lists, preparation times or numbered instructions into the feed.
const editorial=verified.filter(f=>!/^Préparation\s*:|^Ingrédients\s*:|^Étape\s*:|^Cuisson\s*:|^Préparer\s|^Assaisonner\s|^Cuire\s|^Servir\s|^Ajouter\s|^Finir\s/i.test(f.text));
const pool=editorial.some(f=>f.text.length>=50)?editorial:verified;
const pick=(intro,closer,tail,max,count)=>{
  const out=[];let size=intro.length+closer.length+tail.length+8;
  for(const fact of pool){
    if(fact.text.length<40||fact.text.length>260)continue;
    if(out.length>=count)break;
    if(size+fact.text.length+2>max)continue;
    out.push(fact);size+=fact.text.length+2;
  }
  return out;
};
const assemble=(intro,middle,closer,tail)=>[intro,...middle.map(f=>f.text),closer].join('\n\n')+tail;
const fallbackFb=pick(phrases.facebook.openers[0],phrases.facebook.closers[0],fbTail,850,source.kind==='culture'?1:2);
const fallbackIg=pick(phrases.instagram.openers[0],phrases.instagram.closers[0],igTail,700,source.kind==='culture'?1:1);
const fallbackFacebook=assemble(phrases.facebook.openers[0],fallbackFb,phrases.facebook.closers[0],fbTail);
const fallbackInstagram=assemble(phrases.instagram.openers[0],fallbackIg,phrases.instagram.closers[0],igTail);
if(!fallbackFb.length||!fallbackIg.length||fallbackFacebook.length<100||fallbackFacebook.length>850||
  fallbackInstagram.length<90||fallbackInstagram.length>700)throw Error('catalogue_insuffisant_pour_legendes');
const validateCaption=(value,contract,tail,min,max)=>{
  if(typeof value!=='string')return{ok:false,reason:'schema_invalide'};
  if(/(?:https?:\/\/|www\.|[a-z0-9-]+\.(?:com|fr|org|net)\b)/i.test(value))return{ok:false,reason:'url_interdite'};
  const blocks=String(value).replace(/\r/g,'').split(/\n+/).map(clean).filter(Boolean);
  if(blocks.length<3||!contract.openers.includes(blocks[0])||
    !contract.closers.includes(blocks[blocks.length-1]))return{ok:false,reason:'texte_non_verifiable'};
  const middle=blocks.slice(1,-1);
  if(!middle.length||middle.some(block=>block.length<40||block.length>260||!factByText.has(block))||
    new Set(middle).size!==middle.length)return{ok:false,reason:'texte_non_verifiable'};
  const text=blocks.join('\n\n')+tail;
  if(text.length<min||text.length>max)return{ok:false,reason:'plages_non_conformes'};
  return{ok:true,text,facts:middle.map(block=>factByText.get(block))};
};
const input=$input.first().json||{},raw=String(input.choices?.[0]?.message?.content??'').trim().replace(/^\x60{3}(?:json)?\s*/i,'').replace(/\s*\x60{3}$/,'');
let modelValidation='absent';
if(raw){
  try{
    const value=JSON.parse(raw),claims=value?.claimsUsed;
    if(!value||typeof value!=='object'||typeof value.facebookCaption!=='string'||
      typeof value.instagramCaption!=='string'||!Array.isArray(claims)||!claims.length)
      modelValidation='schema_invalide';
    else if(claims.some(claim=>typeof claim!=='string'||!rawFacts.includes(claim))||
      new Set(claims).size!==claims.length)modelValidation='preuves_non_verifiables';
    else{
      const fb=validateCaption(value.facebookCaption,phrases.facebook,fbTail,100,850);
      const ig=validateCaption(value.instagramCaption,phrases.instagram,igTail,90,700);
      if(!fb.ok||!ig.ok)modelValidation=!fb.ok?fb.reason:ig.reason;
      else{
        const usedRaw=[...new Set([...fb.facts,...ig.facts].map(f=>f.raw))],claimSet=new Set(claims);
        if(usedRaw.length!==claimSet.size||usedRaw.some(f=>!claimSet.has(f)))
          modelValidation='preuves_non_verifiables';
        else return[{json:{...s,facebookCaption:fb.text,instagramCaption:ig.text,
          claimsUsed:usedRaw,generationMode:'ollama_borne',modelValidation:'valide_transmis'}}];
      }
    }
  }catch{modelValidation='json_invalide'}
}
const fallbackUsed=[...new Set([...fallbackFb,...fallbackIg].map(f=>f.raw))];
return[{json:{...s,facebookCaption:fallbackFacebook,instagramCaption:fallbackInstagram,
  claimsUsed:fallbackUsed,generationMode:'catalogue_deterministe',modelValidation}}];

const incoming=$input.first().json;
const d=String(incoming?.data?.Decision??incoming?.Decision??incoming?.body?.Decision??'').trim();
const note=String(incoming?.data?.Commentaire??incoming?.Commentaire??incoming?.body?.Commentaire??'').trim().slice(0,2000);
const saved=$('Enregistrer le brouillon').first().json;
const rawId=saved?.id;
const text=typeof rawId==='string'?rawId.trim():typeof rawId==='number'&&Number.isSafeInteger(rawId)?String(rawId):'';
if(!/^(?:0*[1-9]\d*)$/.test(text))throw Error('brouillon_non_identifie');
const id=text.replace(/^0+/,'');
if(id.length>19||(id.length===19&&id>'9223372036854775807'))throw Error('brouillon_non_identifie');
const decision=d==='Approuver'?'approved':d==='Demander une modification'?'revision_requested':'rejected';
if(decision==='revision_requested'&&!note)throw Error('commentaire_requis_pour_modification');
return [{json:{id,decision,note}}];
